def refs(*ids):return '<span class="refs">来源：'+ '、'.join(f'<a href="#s-{i}">{i}</a>' for i in ids)+'</span>'
def tag(k):return f'<span class="tag tag-{k}">'+{'fact':'官方事实','calc':'自行计算','view':'研究判断','assume':'情景假设'}[k]+'</span>'
def box(title,body,kind='limit'):return f'<aside class="box {kind}"><b>{title}</b><div>{body}</div></aside>'
def table(headers,rows,cls='',ident=''):
 ident_attr=f' id="{ident}"' if ident else ''
 return f'<div class="table-wrap" tabindex="0" aria-label="可横向滚动的数据表"><table class="{cls}"{ident_attr}><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def fig(name,caption):
 svg=(O/'charts'/(name+'.svg')).read_text();svg=svg[svg.find('<svg'):];svg=svg.replace('<svg ','<svg role="img" aria-label="'+e(caption)+'" ',1)
 for ident in set(re.findall(r'\bid="([^"]+)"',svg)):
  new=name+'-'+ident;svg=svg.replace('id="'+ident+'"','id="'+new+'"').replace('url(#'+ident+')','url(#'+new+')').replace('href="#'+ident+'"','href="#'+new+'"')
 return f'<figure class="chart" id="chart-{name}"><button class="zoom" data-chart="chart-{name}" aria-label="放大图表">放大</button>{svg}<figcaption>{caption}</figcaption></figure>'
